#!/usr/bin/env bash
# Builds the Claude Code plugin files from the prompts in prompt/ (the single source of truth).
#   ./scripts/build.sh           # regenerate
#   ./scripts/build.sh --check   # CI: fail if generated files are out of date
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
P="$ROOT/prompt"
PLUGIN="$ROOT/plugins/cleancode"
HEADER="<!-- GENERATED by scripts/build.sh from prompt/ — do not edit by hand. -->"

# Shared skill pieces -------------------------------------------------------

# Facts about the repository, injected before Claude reads the skill.
skill_context() {
  cat <<'EOF'

## Project facts (collected automatically when the skill started)

```text
!`bash ${CLAUDE_PLUGIN_ROOT}/scripts/context.sh`
```

Use these facts in Phase 1 instead of re-running the same commands. If the working tree is NOT CLEAN, stop and follow directive 5 (in `audit` mode you may continue, because nothing gets changed).

EOF
}

skill_frontmatter_common() {
  cat <<'EOF'
allowed-tools: Bash(bash ${CLAUDE_PLUGIN_ROOT}/scripts/context.sh)
hooks:
  PreToolUse:
    - matcher: "Edit|Write"
      hooks:
        - type: command
          command: "bash ${CLAUDE_PLUGIN_ROOT}/scripts/guard.sh"
EOF
}

# Targets ------------------------------------------------------------------

build_agent_clean_code() {
  cat <<'EOF'
---
name: clean-code
description: Clean Code Agent by openways.ai. Audits and refactors code without changing behaviour — dead code, naming, duplication, structure, error handling, security hygiene, tests, AI-generated residue. Use when the user asks to clean up, refactor, tidy, or audit code quality, or to tidy the files a large change just touched.
model: inherit
color: green
---
EOF
  echo "$HEADER"
  echo
  cat "$P/clean-code-agent.md" "$P/claude-code-addendum.md"
}

build_agent_challenger() {
  cat <<'EOF'
---
name: challenger
description: Sceptical second reviewer for the Clean Code Agent by openways.ai. Give it candidate findings (unused code, suspected bugs, refactors) with locations; it tries to disprove each one and returns CONFIRMED / REFUTED / UNCERTAIN with confidence and evidence. Read-only.
tools: Read, Grep, Glob, Bash
disallowedTools: Edit, Write, NotebookEdit
model: inherit
color: yellow
---
EOF
  echo "$HEADER"
  echo
  cat "$P/challenger.md"
}

build_skill_clean() {
  cat <<'EOF'
---
name: clean
description: Run the openways.ai Clean Code Agent — audit or refactor this codebase without changing behaviour. Modes are audit (report only), safe (default, low-risk fixes), deep (plan first, then structural refactors).
argument-hint: "[audit|safe|deep] [path | diff]"
disable-model-invocation: true
EOF
  skill_frontmatter_common
  echo "---"
  echo "$HEADER"
  cat <<'EOF'

**Task:** Run the Clean Code Agent described below.

**Arguments:** `$ARGUMENTS`
- The first word, if it is `audit`, `safe`, or `deep`, is the mode. Otherwise the mode is `safe`.
- The rest is the scope: a path, a module, or `diff` (files changed on the current branch compared with the default branch). Empty means the whole repository.

State the mode and scope in your first message, then start with Phase 1.
EOF
  skill_context
  cat "$P/clean-code-agent.md" "$P/claude-code-addendum.md"
}

build_skill_audit() {
  cat <<'EOF'
---
name: audit
description: Read-only code-quality audit by the openways.ai Clean Code Agent. Produces a prioritised report with file:line findings and changes nothing — editing tools are switched off for this skill.
argument-hint: "[path | diff]"
disable-model-invocation: true
disallowed-tools: Edit, Write, NotebookEdit
EOF
  skill_frontmatter_common
  echo "---"
  echo "$HEADER"
  cat <<'EOF'

**Task:** Run the Clean Code Agent described below in **`audit` mode**. This is enforced: editing tools are not available, so do not try to change files — not even through shell commands.

**Scope:** `$ARGUMENTS` — a path, a module, or `diff` (files changed on the current branch compared with the default branch). Empty means the whole repository.

State the scope in your first message, then start with Phase 1. End with the report from §7 in your reply.
EOF
  skill_context
  cat "$P/clean-code-agent.md" "$P/claude-code-addendum.md"
}

# In a skill, "!" followed by a backtick runs a shell command. Never let prompt text trigger that by accident.
if grep -n '!`' "$P"/*.md; then
  echo "error: prompt text contains '!\`', which Claude Code would execute as a shell command — rephrase it" >&2
  exit 1
fi

TARGETS=(
  "agent_clean_code:agents/clean-code.md"
  "agent_challenger:agents/challenger.md"
  "skill_clean:skills/clean/SKILL.md"
  "skill_audit:skills/audit/SKILL.md"
)

check=0
[[ "${1:-}" == "--check" ]] && check=1

status=0
for t in "${TARGETS[@]}"; do
  fn="build_${t%%:*}"; out="$PLUGIN/${t#*:}"
  if (( check )); then
    if ! diff -q <("$fn") "$out" >/dev/null 2>&1; then
      echo "out of date: ${out#"$ROOT"/} (run ./scripts/build.sh)"; status=1
    fi
  else
    mkdir -p "$(dirname "$out")"
    "$fn" > "$out"
    echo "built ${out#"$ROOT"/}"
  fi
done
exit $status
